#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(Seurat);library(data.table);library(Matrix)})
args<-commandArgs(trailingOnly=TRUE)
if(length(args)!=5L)stop('Usage: dataset rds metadata cycle output')
dataset<-args[[1]];rds<-args[[2]];metadata_path<-args[[3]];cycle_path<-args[[4]];out<-args[[5]];part<-paste0(out,'.part')
if(dir.exists(out)||dir.exists(part))stop('Refusing existing output');dir.create(part,recursive=TRUE)
SEED<-2621073L;MIN_MY<-50L;MIN_T<-50L
MY<-list(MY_MTA_RESPONSE=c('ARG1','VEGFA','IL10','TIMP1'),MY_SPP1_STATE_NO_SPP1=c('GPNMB','LGALS3','FABP5','CD9','LPL'),MY_C1QC_STATE=c('C1QA','C1QB','C1QC'),MY_IMMUNOSUPPRESSION_NO_IL10=c('TGFB1','VSIG4','MARCO','CD274','IDO1'))
TP<-list(T_DYSFUNCTION=c('PDCD1','CTLA4','LAG3','HAVCR2','TIGIT','TOX','CXCL13','ENTPD1'))
NKP<-list(T_CYTOTOXICITY=c('NKG7','GNLY','GZMB','PRF1','CTSW'))
REL<-data.table(relation_id=paste0('E0',1:9),predictor=c('MY_MTA_RESPONSE','MY_MTA_RESPONSE','MY_SPP1_STATE_NO_SPP1','MY_SPP1_STATE_NO_SPP1','MY_SPP1_VS_C1QC','MY_IMMUNOSUPPRESSION_NO_IL10','MY_MTA_RESPONSE','MY_SPP1_STATE_NO_SPP1','MY_ECOSYSTEM_COMPOSITE'),outcome=c('T_DYSFUNCTION','T_CYTOTOXICITY','T_DYSFUNCTION','T_CYTOTOXICITY','TREG_FRACTION','T_DYSFUNCTION','TREG_FRACTION','TREG_FRACTION','T_SUPPRESSION_COMPOSITE'),expected=c('positive','negative','positive','negative','positive','positive','positive','positive','positive'))
score_ctrl<-function(e,genes,ctrl_size,n_bins=25L){genes<-unique(intersect(toupper(genes),rownames(e)));av<-Matrix::rowMeans(e);pool<-rownames(e)[is.finite(av)];v<-av[is.finite(av)];n<-as.integer(round(length(v)/(n_bins-1L)));b<-floor(frank(v,ties.method='min')/n);names(b)<-pool;set.seed(SEED);ct<-character();for(x in unique(b[genes])){z<-names(b)[b==x & !names(b)%chin%genes];if(length(z)>ctrl_size)z<-sample(z,ctrl_size);ct<-union(ct,z)};as.numeric(Matrix::colMeans(e[genes,,drop=FALSE])-Matrix::colMeans(e[ct,,drop=FALSE]))}
programs<-function(e,sets,cycle){small<-as.matrix(e[intersect(unique(c(unlist(sets),cycle$S,cycle$G2M)),rownames(e)),,drop=FALSE]);z<-small[intersect(unique(unlist(sets)),rownames(small)),,drop=FALSE];sdv<-apply(z,1,sd);z<-sweep(sweep(z,1,rowMeans(z),'-'),1,sdv,'/');z[!is.finite(z)]<-0;ss<-score_ctrl(e,cycle$S,43L);gg<-score_ctrl(e,cycle$G2M,54L);ans<-data.table(cell_id=colnames(e),S=ss,G=gg);cov<-list();i<-0L;for(nm in names(sets)){g<-intersect(sets[[nm]],rownames(z));i<-i+1L;cov[[i]]<-data.table(dataset=dataset,lineage=nm,program=nm,n_frozen=length(sets[[nm]]),n_present=length(g),present=paste(g,collapse=';'));raw<-colMeans(z[g,,drop=FALSE]);ans[[paste0(nm,'_RAW')]]<-raw;ans[[nm]]<-as.numeric(residuals(lm(raw~ss+gg)))};list(scores=ans,coverage=rbindlist(cov))}
rho_test<-function(x,y){ok<-is.finite(x)&is.finite(y);if(sum(ok)<5||uniqueN(x[ok])<3||uniqueN(y[ok])<3)return(c(rho=NA,p=NA,n=sum(ok)));q<-suppressWarnings(cor.test(x[ok],y[ok],method='spearman',exact=FALSE));c(rho=unname(q$estimate),p=q$p.value,n=sum(ok))}
partial_rho<-function(x,y,cov){ok<-is.finite(x)&is.finite(y)&apply(cov,1,function(v)all(is.finite(v)));if(sum(ok)<8)return(c(rho=NA,p=NA,n=sum(ok)));xr<-residuals(lm.fit(cbind(1,as.matrix(cov[ok,,drop=FALSE])),x[ok]));yr<-residuals(lm.fit(cbind(1,as.matrix(cov[ok,,drop=FALSE])),y[ok]));rho_test(xr,yr)}
meta<-fread(metadata_path);obj<-readRDS(rds);eall<-LayerData(obj[['RNA']],layer='data');source_cells<-ncol(obj)
if(dataset=='GSE207493'){
 meta[,`:=`(cell_id=cell_barcode,seurat_cell_name=paste0('GSE207493__GSE207493__',sub('^([^_]+)_','\\1__',cell_barcode)),patient_key=paste0('GSE207493::',sample),patient_id=sample,timepoint='Single',treatment='Unknown',response='Unknown')]
 meta[,myeloid:=cell_type%chin%c('Myeloid','Dendritic')];meta[,tcell:=cell_type%chin%c('Exhausted_T','CD4_T','CD8_T','Treg','Proliferating_T')];meta[,tnk:=tcell|cell_type=='NK'];meta[,treg:=cell_type=='Treg'];meta[,immune:=myeloid|tcell|cell_type%chin%c('NK','B_cell')];meta[,broad:=cell_type]
}else{
 meta[,myeloid:=phase7_broad_annotation=='Myeloid'];meta[,tcell:=phase7_broad_annotation=='T_cell'];meta[,tnk:=phase7_broad_annotation%chin%c('T_cell','NK_cell')];meta[,treg:=phase7_fine_annotation=='Treg'];meta[,immune:=phase7_broad_annotation%chin%c('Myeloid','T_cell','NK_cell','B_cell')];meta[,broad:=phase7_broad_annotation]
}
if(length(setdiff(meta$seurat_cell_name,colnames(eall))))stop('ID mismatch')
sel<-meta[immune==TRUE];e<-eall[,match(sel$seurat_cell_name,colnames(eall)),drop=FALSE];colnames(e)<-sel$cell_id;rm(obj,eall);gc();u<-toupper(rownames(e));dup<-unique(u[duplicated(u)|duplicated(u,fromLast=TRUE)]);e<-e[!u%chin%dup,,drop=FALSE];rownames(e)<-u[!u%chin%dup]
cy<-fread(cycle_path);cycle<-list(S=toupper(cy[phase=='S',gene]),G2M=toupper(cy[phase=='G2M',gene]))
my_meta<-sel[myeloid==TRUE];t_meta<-sel[tcell==TRUE];tnk_meta<-sel[tnk==TRUE]
my<-programs(e[,match(my_meta$cell_id,colnames(e)),drop=FALSE],MY,cycle);tt<-programs(e[,match(t_meta$cell_id,colnames(e)),drop=FALSE],TP,cycle);nn<-programs(e[,match(tnk_meta$cell_id,colnames(e)),drop=FALSE],NKP,cycle)
my_sc<-cbind(my_meta[,.(cell_id,patient_key,patient_id,timepoint,treatment,response)],my$scores[,!"cell_id",with=FALSE]);t_sc<-cbind(t_meta[,.(cell_id,patient_key,timepoint)],tt$scores[,!"cell_id",with=FALSE]);n_sc<-cbind(tnk_meta[,.(cell_id,patient_key,timepoint)],nn$scores[,!"cell_id",with=FALSE])
my_unit<-my_sc[,lapply(.SD,median,na.rm=TRUE),by=.(patient_key,patient_id,timepoint,treatment,response),.SDcols=patterns('^MY_')];my_unit<-merge(my_unit,my_sc[,.(N_MY=.N),by=.(patient_key,timepoint)],by=c('patient_key','timepoint'))
t_unit<-t_sc[,lapply(.SD,median,na.rm=TRUE),by=.(patient_key,timepoint),.SDcols=patterns('^T_DYSFUNCTION')];t_unit<-merge(t_unit,t_sc[,.(N_T=.N),by=.(patient_key,timepoint)],by=c('patient_key','timepoint'))
n_unit<-n_sc[,lapply(.SD,median,na.rm=TRUE),by=.(patient_key,timepoint),.SDcols=patterns('^T_CYTOTOXICITY')];n_unit<-merge(n_unit,n_sc[,.(N_TNK=.N),by=.(patient_key,timepoint)],by=c('patient_key','timepoint'))
counts<-sel[,.(N_IMMUNE=.N,N_MY_COMP=sum(myeloid),N_T_COMP=sum(tcell),N_NK=sum(tnk&!tcell),N_TREG=sum(treg)),by=.(patient_key,timepoint)]
counts[,`:=`(MYELOID_FRACTION=N_MY_COMP/N_IMMUNE,T_FRACTION=N_T_COMP/N_IMMUNE,NK_FRACTION=N_NK/N_IMMUNE)]
has_treg<-sum(sel$treg)>0L;counts[,TREG_FRACTION:=if(has_treg)N_TREG/pmax(N_T_COMP,1L) else NA_real_]
unit<-Reduce(function(x,y)merge(x,y,by=c('patient_key','timepoint'),all=FALSE),list(my_unit,t_unit,n_unit,counts));unit<-unit[N_MY>=MIN_MY & N_T>=MIN_T];unit[,MY_SPP1_VS_C1QC:=MY_SPP1_STATE_NO_SPP1-MY_C1QC_STATE]
numcols<-setdiff(names(unit),c('patient_key','patient_id','timepoint','treatment','response'))
patient<-unit[,lapply(.SD,median,na.rm=TRUE),by=.(patient_key,patient_id,response),.SDcols=numcols]
zs<-function(x){s<-sd(x,na.rm=TRUE);if(!is.finite(s)||s==0)return(rep(0,length(x)));(x-mean(x,na.rm=TRUE))/s}
patient[,MY_ECOSYSTEM_COMPOSITE:=(zs(MY_MTA_RESPONSE)+zs(MY_SPP1_STATE_NO_SPP1)+zs(MY_IMMUNOSUPPRESSION_NO_IL10))/3]
patient[,T_SUPPRESSION_COMPOSITE:=if(has_treg)(zs(T_DYSFUNCTION)-zs(T_CYTOTOXICITY)+zs(TREG_FRACTION))/3 else (zs(T_DYSFUNCTION)-zs(T_CYTOTOXICITY))/2]
rows<-list();sens<-list();i<-0L;j<-0L
for(r in seq_len(nrow(REL))){rr<-REL[r];x<-patient[[rr$predictor]];y<-patient[[rr$outcome]];test<-rho_test(x,y);if(!is.finite(test['rho']))next;i<-i+1L;rows[[i]]<-data.table(dataset=dataset,relation_id=rr$relation_id,predictor=rr$predictor,outcome=rr$outcome,expected=rr$expected,n_patients=test['n'],rho=test['rho'],p_value=test['p']);cov<-patient[,.(LOG_N=log1p(N_IMMUNE),MYELOID_FRACTION,T_FRACTION,NK_FRACTION)];pt<-partial_rho(x,y,cov);j<-j+1L;sens[[j]]<-data.table(dataset=dataset,relation_id=rr$relation_id,n_patients=pt['n'],partial_rho=pt['rho'],p_value=pt['p'])}
summary<-rbindlist(rows);summary[,q_value:=p.adjust(p_value,'BH')];summary[,decision:=fifelse(q_value<0.05 & ((expected=='positive'&rho>0)|(expected=='negative'&rho<0)),'COHORT_SUPPORTED',fifelse(q_value<0.05,'DIRECTION_CONFLICT','NOT_SUPPORTED'))]
sensitivity<-rbindlist(sens);sensitivity[,q_value:=p.adjust(p_value,'BH')]
longitudinal<-data.table();long_rel<-data.table()
if(dataset=='GSE264586'){
 order<-c(Baseline=1L,Cycle2=2L,End_of_treatment=3L);u<-copy(unit);u[,ord:=order[timepoint]];eligible<-u[,if(.N>1).SD[c(which.min(ord),which.max(ord))],by=patient_key];vars<-c('MY_MTA_RESPONSE','MY_SPP1_STATE_NO_SPP1','MY_IMMUNOSUPPRESSION_NO_IL10','T_DYSFUNCTION','T_CYTOTOXICITY','TREG_FRACTION');longitudinal<-eligible[,c(list(baseline_time=timepoint[1],last_time=timepoint[2]),setNames(lapply(vars,function(v)get(v)[2]-get(v)[1]),paste0('delta_',vars))),by=patient_key];lr<-list();for(r in seq_len(nrow(REL))){rr<-REL[r];px<-paste0('delta_',rr$predictor);py<-paste0('delta_',rr$outcome);if(px%chin%names(longitudinal)&&py%chin%names(longitudinal)){z<-rho_test(longitudinal[[px]],longitudinal[[py]]);lr[[length(lr)+1L]]<-data.table(relation_id=rr$relation_id,n_patients=z['n'],delta_rho=z['rho'],p_value=z['p'])}};long_rel<-rbindlist(lr,fill=TRUE)
}
response_test<-data.table()
if(dataset=='GSE294109'){
 vars<-c('MY_MTA_RESPONSE','MY_SPP1_STATE_NO_SPP1','MY_IMMUNOSUPPRESSION_NO_IL10','T_DYSFUNCTION','T_CYTOTOXICITY','TREG_FRACTION','MY_ECOSYSTEM_COMPOSITE','T_SUPPRESSION_COMPOSITE');z<-patient[response%chin%c('CR','PR','No_effect')];rr<-lapply(vars,function(v){a<-z[response%chin%c('CR','PR'),get(v)];b<-z[response=='No_effect',get(v)];w<-suppressWarnings(wilcox.test(a,b,exact=FALSE));data.table(variable=v,n_response=length(a),n_no_effect=length(b),median_response=median(a),median_no_effect=median(b),delta=median(a)-median(b),p_value=w$p.value)});response_test<-rbindlist(rr);response_test[,q_value:=p.adjust(p_value,'BH')]
}
fwrite(rbindlist(list(my$coverage,tt$coverage,nn$coverage)),file.path(part,paste0(dataset,'_program_coverage_v1.tsv')),sep='\t');fwrite(unit,file.path(part,paste0(dataset,'_unit_scores_v1.tsv.gz')),sep='\t');fwrite(patient,file.path(part,paste0(dataset,'_patient_scores_v1.tsv')),sep='\t');fwrite(summary,file.path(part,paste0(dataset,'_primary_relations_v1.tsv')),sep='\t');fwrite(sensitivity,file.path(part,paste0(dataset,'_composition_sensitivity_v1.tsv')),sep='\t');if(nrow(longitudinal))fwrite(longitudinal,file.path(part,paste0(dataset,'_longitudinal_deltas_v1.tsv')),sep='\t');if(nrow(long_rel))fwrite(long_rel,file.path(part,paste0(dataset,'_longitudinal_relations_v1.tsv')),sep='\t');if(nrow(response_test))fwrite(response_test,file.path(part,paste0(dataset,'_response_exploratory_v1.tsv')),sep='\t');fwrite(data.table(dataset=dataset,source_cells=source_cells,immune_cells=nrow(sel),myeloid_cells=nrow(my_meta),t_cells=nrow(t_meta),tnk_cells=nrow(tnk_meta),eligible_units=nrow(unit),patients=nrow(patient),treg_evaluable=has_treg,status='PASS_PHASE72_DATASET_V1'),file.path(part,paste0(dataset,'_status_v1.tsv')),sep='\t');file.rename(part,out);cat(sprintf('{"status":"PASS_PHASE72_DATASET_V1","dataset":"%s","patients":%d}\n',dataset,nrow(patient)))
